/* Thread 3 hero sprite - archetype: ASSEMBLE, 96 frames, 12x8 grid, native ratio 2:3 */
.hero-sprite {
  aspect-ratio: 2 / 3;
  height: min(78vh, 720px);
  width: auto;
  margin: 0 auto;
  background-image: url('sprite.webp');
  background-repeat: no-repeat;
  background-size: 1200% 800%; /* percentage, not px - required, see this project's own bleed-bug finding */
  background-position: 100% 100%; /* unconditional base state: the chosen fallback frame's grid cell (11,7), frame index 95 - per-archetype choice (src/archetypes.js), not always the last frame and NOT always "100% 100%" even when it is, since frameCount doesn't always fill the grid exactly */
}

@supports (animation-timeline: scroll()) {
  .hero-sprite {
    animation: hero-scrub-assemble linear both;
    animation-timeline: scroll(root block);
  }
}

